import java.io.File; import java.io.PrintWriter; import ghidra.app.decompiler.DecompInterface; import ghidra.app.decompiler.DecompileResults; import ghidra.app.script.GhidraScript; import ghidra.program.model.listing.Function; import ghidra.program.model.listing.FunctionIterator; public class ghidra_decompile extends GhidraScript { @Override public void run() throws Exception { String[] args = getScriptArgs(); if (args.length < 1) { println("Usage:"); println(" -postScript ghidra_decompile.java <output.c>"); return; } File outputFile = new File(args[0]); File parent = outputFile.getParentFile(); if (parent != null) { parent.mkdirs(); } println("Input : " + currentProgram.getExecutablePath()); println("Output: " + outputFile.getAbsolutePath()); DecompInterface decompiler = new DecompInterface(); decompiler.setSimplificationStyle("decompile"); if (!decompiler.openProgram(currentProgram)) { printerr("Failed to initialize Ghidra decompiler."); return; } int total = currentProgram .getFunctionManager() .getFunctionCount(); int count = 0; int success = 0; int failed = 0; try (PrintWriter out = new PrintWriter(outputFile)) { out.println("/*"); out.println(" * Ghidra decompilation"); out.println(" *"); out.println(" * File: " + currentProgram.getName()); out.println(" *"); out.println(" * WARNING:"); out.println(" * This is C-like pseudocode generated by Ghidra."); out.println(" * It is NOT the original C/C++ source code."); out.println(" */"); out.println(); FunctionIterator functions = currentProgram .getFunctionManager() .getFunctions(true); while (functions.hasNext() && !monitor.isCancelled()) { Function function = functions.next(); count++; println( "[" + count + "/" + total + "] " + function.getName() ); DecompileResults result = decompiler.decompileFunction( function, 60, monitor ); if ( result != null && result.decompileCompleted() && result.getDecompiledFunction() != null ) { out.println(); out.println( "/* ================================================== */" ); out.println( " * Function: " + function.getName() ); out.println( " * Address : " + function.getEntryPoint() ); out.println( " * Size : " + function.getBody().getNumAddresses() ); out.println( " * ================================================== */" ); out.println(); out.println( result .getDecompiledFunction() .getC() ); out.println(); success++; } else { out.println(); out.println( "/* ================================================== */" ); out.println( " * Failed to decompile: " + function.getName() ); out.println( " * Address: " + function.getEntryPoint() ); out.println( " * ================================================== */" ); out.println(); failed++; } } } decompiler.dispose(); println(""); println("========================================"); println("Decompilation finished"); println("========================================"); println("Functions : " + total); println("Succeeded : " + success); println("Failed : " + failed); println("Output : " + outputFile.getAbsolutePath()); println("========================================"); } } 